local VegetableGardener = {}
local PRODUCTS = {
    common_root_basket = { name = "Košarica korenja", woodCost = 1, time = 3, cost = 30, happiness = 1, food = 12, description = "Košarica navadnih korenovk za kuhinjo." },
    leafy_greens_crate = { name = "Zaboj zelenja", woodCost = 1, time = 4, cost = 50, happiness = 1, food = 18, description = "Zaboj solat in zelja za grajsko kuhinjo." },
    heirloom_vegetable_hamper = { name = "Dedna košara zelenjave", woodCost = 2, time = 6, cost = 120, happiness = 2, food = 35, prestige = 2, description = "Košara redkih dednih sort za plemiško mizo." },
    pickled_preserves_crate = { name = "Zaboj kisle zelenjave", woodCost = 2, glassCost = 1, saltCost = 1, time = 9, cost = 240, happiness = 2, food = 50, prestige = 4, description = "Kisli pridelki v steklenih kozarcih za zimo." },
    exotic_garden_bounty = { name = "Egzotični pridelki", woodCost = 2, glassCost = 2, saltCost = 1, time = 12, cost = 580, happiness = 4, food = 80, prestige = 10, description = "Egzotična zelenjava iz tople grede za visoke dvorjane." },
    royal_garden_harvest = { name = "Kraljevski vrtni pridelek", woodCost = 3, glassCost = 3, saltCost = 2, silverCost = 1, time = 17, cost = 1500, happiness = 7, food = 150, prestige = 25, description = "Veliki kraljevski pridelek iz kraljevih vrtov za bankete." },
}
local BUILDINGS = {
    kitchen_garden = { name = "Kuhinjski vrt", cost = { gold = 200, wood = 80, stone = 80 }, upkeep = 4, qualityBonus = 5 },
    walled_garden = { name = "Obzidan vrt", cost = { gold = 800, wood = 180, stone = 320, clay = 6 }, upkeep = 16, qualityBonus = 18 },
    greenhouse = { name = "Topla greda", cost = { gold = 2200, wood = 320, stone = 480, glass = 14, iron = 6 }, upkeep = 45, qualityBonus = 30 },
    royal_botanic_garden = { name = "Kraljevski botanični vrt", cost = { gold = 9000, wood = 600, stone = 800, glass = 30, marble = 8 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 50 },
}
VegetableGardener.woodStock = 18; VegetableGardener.glassStock = 8; VegetableGardener.saltStock = 10; VegetableGardener.silverStock = 6; VegetableGardener.productStock = {}; VegetableGardener.buildings = {}; VegetableGardener.maker = nil; VegetableGardener.activeMaking = {}; VegetableGardener.totalProducts = 0; VegetableGardener.dayTimer = 0
function VegetableGardener.init() VegetableGardener.woodStock=18; VegetableGardener.glassStock=8; VegetableGardener.saltStock=10; VegetableGardener.silverStock=6; VegetableGardener.productStock={}; VegetableGardener.buildings={}; VegetableGardener.maker=nil; VegetableGardener.activeMaking={}; VegetableGardener.totalProducts=0; VegetableGardener.dayTimer=0; print("[VegetableGardener] Royal Vegetable Gardener System initialized (6 products, 4 buildings)") end
function VegetableGardener.hireMaker(n,s) s=s or math.random(55,90); local c=380+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; VegetableGardener.maker={name=n or ("Vrtnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrtnar najet: %s (spretnost: %d)",VegetableGardener.maker.name,s),"success") end; return true end
function VegetableGardener.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function VegetableGardener.build(id) local ok,e=VegetableGardener.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(VegetableGardener.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function VegetableGardener.getQualityBonus() local b=0; for _,bd in ipairs(VegetableGardener.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function VegetableGardener.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and VegetableGardener.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and VegetableGardener.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.saltCost and VegetableGardener.saltStock<(d.saltCost or 0) then return false,"Premalo soli" end; if d.silverCost and VegetableGardener.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if #VegetableGardener.buildings==0 then return false,"Potreben kuhinjski vrt" end; if not VegetableGardener.maker then return false,"Potreben vrtnar" end; return true end
function VegetableGardener.make(pt,qty) qty=qty or 1; local ok,e=VegetableGardener.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then VegetableGardener.woodStock=VegetableGardener.woodStock-d.woodCost*qty end; if d.glassCost then VegetableGardener.glassStock=VegetableGardener.glassStock-d.glassCost*qty end; if d.saltCost then VegetableGardener.saltStock=VegetableGardener.saltStock-d.saltCost*qty end; if d.silverCost then VegetableGardener.silverStock=VegetableGardener.silverStock-d.silverCost*qty end; local t=d.time; if VegetableGardener.maker then t=math.max(1,t-math.floor(VegetableGardener.maker.skill/14)) end; table.insert(VegetableGardener.activeMaking,{id="veg_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Setev: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function VegetableGardener.completeMaking(m) local q=1.0+(VegetableGardener.getQualityBonus()/100); if VegetableGardener.maker then q=q+(VegetableGardener.maker.skill/160) end; q=math.min(2.2,q); VegetableGardener.productStock[m.productType]=(VegetableGardener.productStock[m.productType] or 0)+m.quantity; VegetableGardener.totalProducts=VegetableGardener.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if VegetableGardener.maker then VegetableGardener.maker.itemsMade=VegetableGardener.maker.itemsMade+m.quantity; if math.random()<0.25 then VegetableGardener.maker.skill=math.min(100,VegetableGardener.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pridelek: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"vegetable.harvested",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function VegetableGardener.update(dt) if not _G.state then return end; VegetableGardener.dayTimer=VegetableGardener.dayTimer+dt; if VegetableGardener.dayTimer>=30 then VegetableGardener.dayTimer=0; for i=#VegetableGardener.activeMaking,1,-1 do local m=VegetableGardener.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then VegetableGardener.completeMaking(m); table.remove(VegetableGardener.activeMaking,i) end end; local tu=0; for _,bd in ipairs(VegetableGardener.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if VegetableGardener.maker then tu=tu+10 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function VegetableGardener.getStats() return {woodStock=VegetableGardener.woodStock,glassStock=VegetableGardener.glassStock,saltStock=VegetableGardener.saltStock,silverStock=VegetableGardener.silverStock,productStock=VegetableGardener.productStock,numBuildings=#VegetableGardener.buildings,hasMaker=VegetableGardener.maker~=nil,makerName=VegetableGardener.maker and VegetableGardener.maker.name or "—",makerSkill=VegetableGardener.maker and VegetableGardener.maker.skill or 0,activeMaking=#VegetableGardener.activeMaking,totalProducts=VegetableGardener.totalProducts} end
return VegetableGardener
